<template>
  <div class="marketplace-console"><el-card shadow="never"><h1 class="marketplace-heading">入驻商家</h1><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon class="marketplace-feedback" /><el-alert v-if="notice" :title="notice" role="status" aria-live="polite" type="success" :closable="false" show-icon class="marketplace-feedback" /><div class="marketplace-toolbar"><label for="platform-merchant-review-filter">审核状态</label><el-select id="platform-merchant-review-filter" aria-label="商家审核状态" v-model="reviewStatus" placeholder="全部审核状态" clearable :disabled="loading || busy"><el-option v-for="(label, index) in statuses" :key="index" :value="index" :label="label" /></el-select><el-button :disabled="loading || busy" @click="search">查询</el-button><el-button v-if="can('marketplace-merchants-create')" type="primary" :disabled="busy" @click="edit(null)">建立商家</el-button></div>
    <el-table v-loading="loading" :data="rows" border><el-table-column prop="mer_id" label="商家编号" width="110" /><el-table-column prop="name" label="商家名称" min-width="180" /><el-table-column label="审核状态" width="115"><template slot-scope="scope">{{ statuses[scope.row.review_status] }}</template></el-table-column><el-table-column prop="after_sale_contact" label="售后联系方式" min-width="170" /><el-table-column label="经营状态" min-width="130"><template slot-scope="scope">{{ scope.row.closed_at ? '已关闭' : scope.row.accept_orders ? '接受订单' : '暂不接单' }}<p v-if="scope.row.closed_at" class="marketplace-note">不能通过经营开关重新开店</p></template></el-table-column><el-table-column label="操作" min-width="280"><template slot-scope="scope"><div class="marketplace-actions"><el-button v-if="can('marketplace-merchants-read')" size="mini" :disabled="busy"  :aria-label="'商家详情 ' + scope.row.name" @click="read(scope.row)">详情</el-button><el-button v-if="can('marketplace-merchants-read') && can('marketplace-merchants-update')" size="mini" :disabled="busy"  :aria-label="'编辑商家资料 ' + scope.row.name" @click="edit(scope.row)">编辑资料</el-button><el-button v-if="can('marketplace-merchants-read') && can('marketplace-merchants-review') && scope.row.review_status !== 1 && scope.row.closed_at === null" size="mini" :disabled="busy"  :aria-label="'审核通过商家 ' + scope.row.name" @click="approve(scope.row)">审核通过</el-button><el-button v-if="can('marketplace-merchants-read') && can('marketplace-merchants-review')" size="mini" :disabled="busy" :aria-label="'修改商家审核状态 ' + scope.row.name" @click="openReview(scope.row)">审核状态</el-button><el-button v-if="can('marketplace-merchants-read') && can('marketplace-merchants-flags')" size="mini" :disabled="busy || scope.row.closed_at !== null" :aria-label="'修改商家经营开关 ' + scope.row.name" @click="openFlags(scope.row)">经营开关</el-button><el-button v-if="canExitPrecheck" size="mini" :disabled="loading || busy" :aria-label="'商家退出预检 ' + scope.row.name" @click="openExit(scope.row)">退出预检</el-button><el-button v-if="can('marketplace-merchants-admin-employee') && scope.row.review_status === 1 && scope.row.closed_at === null" size="mini" :disabled="busy"  :aria-label="'建立商家管理员 ' + scope.row.name" @click="openAdmin(scope.row)">建立管理员</el-button><el-button v-if="canReissue(scope.row)" size="mini" :disabled="busy" :aria-label="'补发首次设置链接 ' + scope.row.name" @click="openAdmin(scope.row, 'reissue')">补发首次设置链接</el-button></div></template></el-table-column></el-table><div class="marketplace-pagination"><el-pagination :current-page="page" :page-size="limit" :pager-count="5" :total="count" layout="prev, pager, next" @current-change="changePage" /></div>
  </el-card>
    <el-dialog title="商家退出预检" :visible.sync="exitVisible" width="min(94vw, 760px)" custom-class="marketplace-dialog" :close-on-click-modal="false" :before-close="closeExit" @closed="clearExit">
      <p class="marketplace-note" style="overflow-wrap: anywhere">商家：{{ exitMerchant ? exitMerchant.name : '正在读取' }}（{{ exitTarget }}）</p>
      <el-alert v-if="exitError" :title="exitError" type="error" :closable="false" show-icon class="marketplace-feedback" />
      <el-alert v-if="exitReport" :title="exitSummary" :type="exitSummaryType" role="status" aria-live="polite" :closable="false" show-icon class="marketplace-feedback" />
      <p v-if="exitLoading" class="marketplace-note" role="status" aria-live="polite">正在核查当前责任，请稍候。</p>
      <p v-if="exitReport" class="marketplace-note">核查时间：{{ formatExitTime(exitReport.checked_at) }}</p>
      <el-table :data="exitRows" row-key="key" border v-loading="exitLoading">
        <el-table-column label="责任项" min-width="100"><template slot-scope="scope">{{ exitLabels[scope.row.key] }}</template></el-table-column>
        <el-table-column label="状态" min-width="110"><template slot-scope="scope">{{ exitStateLabels[scope.row.state] || '尚未核实' }}</template></el-table-column>
        <el-table-column label="数量" width="80"><template slot-scope="scope">{{ scope.row.state === 'UNKNOWN' || scope.row.count === null ? '未核实' : scope.row.count }}</template></el-table-column>
        <el-table-column label="原因" min-width="240"><template slot-scope="scope"><p v-for="(reason, index) in scope.row.reasons" :key="index" class="marketplace-note" style="overflow-wrap: anywhere">{{ reason.message }}</p><span v-if="!scope.row.reasons.length">{{ scope.row.state ? '无补充说明' : '尚未取得当前预检结果' }}</span></template></el-table-column>
      </el-table>
      <p class="marketplace-note">关闭时将重新核对当前责任，并保留历史商品、订单与售后资料。已关闭商家不支持重新开店。</p>
      <div class="marketplace-actions">
        <el-button :disabled="busy || !exitContext" :loading="exitLoading" @click="refreshExit">刷新预检</el-button>
        <el-button v-if="can('marketplace-merchants-close')" type="primary" :disabled="!exitCanClose" :loading="exitSending" @click="submitExit">确认关闭商家</el-button>
        <el-button :disabled="busy" @click="closeExit()">取消</el-button>
      </div>
    </el-dialog>
    <el-dialog :title="editId ? '修改商家资料' : '建立商家'" :visible.sync="editorVisible" width="min(94vw, 600px)" custom-class="marketplace-dialog" :close-on-click-modal="false" :before-close="closeEditor"><el-alert v-if="editorError" :title="editorError" type="error" :closable="false" show-icon /><el-form label-position="top" @submit.native.prevent="save"><el-form-item label="商家名称" for="platform-merchant-name"><el-input id="platform-merchant-name" label="商家名称" aria-label="商家名称" v-model="form.name" maxlength="128" :disabled="busy" /></el-form-item><el-form-item label="店铺标识图片地址" for="platform-merchant-logo"><el-input id="platform-merchant-logo" label="店铺标识图片地址" aria-label="店铺标识图片地址" v-model="form.logo" maxlength="512" :disabled="busy" /></el-form-item><el-form-item label="售后联系方式" for="platform-merchant-after_sale_contact"><el-input id="platform-merchant-after_sale_contact" label="售后联系方式" aria-label="售后联系方式" v-model="form.after_sale_contact" maxlength="255" :disabled="busy" /></el-form-item><el-form-item label="发货说明" for="platform-merchant-shipping_note"><el-input id="platform-merchant-shipping_note" label="发货说明" aria-label="发货说明" v-model="form.shipping_note" type="textarea" maxlength="1000" :disabled="busy" /></el-form-item><div class="marketplace-actions"><el-button type="primary" native-type="submit" :loading="busy" :disabled="busy">保存商家</el-button><el-button :disabled="busy" @click="editorVisible = false">取消</el-button></div></el-form></el-dialog>
    <el-dialog title="商家详情" :visible.sync="detailVisible" width="min(94vw, 660px)" custom-class="marketplace-dialog"><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon /><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="商家编号">{{ detail.mer_id }}</el-descriptions-item><el-descriptions-item label="名称">{{ detail.name }}</el-descriptions-item><el-descriptions-item label="审核状态">{{ statuses[detail.review_status] }}</el-descriptions-item><el-descriptions-item label="售后联系方式">{{ detail.after_sale_contact }}</el-descriptions-item><el-descriptions-item label="发货说明">{{ detail.shipping_note }}</el-descriptions-item><el-descriptions-item label="经营状态">{{ detail.closed_at ? '已关闭' : detail.accept_orders ? '接受订单' : '暂不接单' }}</el-descriptions-item></el-descriptions><p v-if="detail && detail.closed_at" class="marketplace-note">商家已关闭，历史资料仍可查看，不能通过经营开关重新开店。</p><div v-if="detail" class="marketplace-actions"><el-button v-if="can('marketplace-merchants-read') && can('marketplace-merchants-review') && detail.review_status !== 1 && detail.closed_at === null" :disabled="busy" @click="approve(detail)">审核通过</el-button><el-button v-if="can('marketplace-merchants-admin-employee') && detail.review_status === 1 && detail.closed_at === null" :disabled="busy" @click="openAdmin(detail)">建立管理员</el-button><el-button v-if="canReissue(detail)" :disabled="busy" :aria-label="'补发首次设置链接 ' + detail.name" @click="openAdmin(detail, 'reissue')">补发首次设置链接</el-button></div></el-dialog>
    <el-dialog title="修改商家审核状态" :visible.sync="reviewVisible" width="min(94vw, 540px)" custom-class="marketplace-dialog" :close-on-click-modal="false" :before-close="closeState"><p v-if="stateMerchant" class="marketplace-note">商家：{{ stateMerchant.name }}（{{ stateMerchant.mer_id }}）</p><el-alert v-if="stateError" :title="stateError" type="error" :closable="false" show-icon /><el-form label-position="top" @submit.native.prevent="saveReview"><el-form-item label="审核状态" for="platform-merchant-review-state"><el-select id="platform-merchant-review-state" v-model="reviewForm" :disabled="busy"><el-option v-for="(label, index) in statuses" :key="index" :label="label" :value="index" /></el-select></el-form-item><div class="marketplace-actions"><el-button type="primary" native-type="submit" :loading="busy" :disabled="busy">保存审核状态</el-button><el-button :disabled="busy" @click="reviewVisible = false">取消</el-button></div></el-form></el-dialog>
    <el-dialog title="修改商家经营开关" :visible.sync="flagsVisible" width="min(94vw, 560px)" custom-class="marketplace-dialog" :close-on-click-modal="false" :before-close="closeState"><p v-if="stateMerchant" class="marketplace-note">商家：{{ stateMerchant.name }}（{{ stateMerchant.mer_id }}）</p><el-alert v-if="stateError" :title="stateError" type="error" :closable="false" show-icon /><el-form label-position="top" @submit.native.prevent="saveFlags"><div class="marketplace-actions"><el-checkbox name="platform-merchant-accept-orders" v-model="flagsForm.accept_orders" :true-label="1" :false-label="0" :disabled="busy">接受新订单</el-checkbox><el-checkbox name="platform-merchant-fulfillment" v-model="flagsForm.fulfillment_enabled" :true-label="1" :false-label="0" :disabled="busy">允许履约</el-checkbox><el-checkbox name="platform-merchant-security-lock" v-model="flagsForm.security_locked" :true-label="1" :false-label="0" :disabled="busy">安全锁定</el-checkbox></div><p class="marketplace-note">保存本商家的当前开关；开启安全锁定后，商家员工无法登录。已关闭商家不能通过经营开关重新开店。</p><div class="marketplace-actions"><el-button type="primary" native-type="submit" :loading="busy" :disabled="busy">保存经营开关</el-button><el-button :disabled="busy" @click="flagsVisible = false">取消</el-button></div></el-form></el-dialog>
    <el-dialog :title="adminMode === 'reissue' ? '补发首次设置链接' : '建立商家管理员'" :visible.sync="adminVisible" width="min(94vw, 620px)" custom-class="marketplace-dialog" :close-on-click-modal="false" :before-close="closeAdmin" @closed="clearDelivery"><p class="marketplace-note">{{ adminMerchant ? adminMerchant.name : '' }}</p><p v-if="adminMode === 'reissue'" class="marketplace-note">请输入本商家已有的员工账号。确认补发后，旧的未使用链接将作废，新链接 24 小时内有效；仅适用于尚未设置密码的员工，不支持重置已设置的密码。</p><el-alert v-if="adminError" :title="adminError" type="error" :closable="false" show-icon /><el-form v-if="!delivery" label-position="top" @submit.native.prevent="createAdmin"><el-form-item label="员工账号" for="platform-adminemployee-account"><el-input id="platform-adminemployee-account" label="员工账号" aria-label="员工账号" v-model="adminForm.account" maxlength="191" autocomplete="off" :disabled="busy" /></el-form-item><el-form-item v-if="adminMode === 'create'" label="员工姓名" for="platform-adminemployee-name"><el-input id="platform-adminemployee-name" label="员工姓名" aria-label="员工姓名" v-model="adminForm.name" maxlength="64" :disabled="busy" /></el-form-item><div class="marketplace-actions"><el-button native-type="submit" type="primary" :loading="busy" :disabled="busy || adminCreated">{{ adminMode === 'reissue' ? '确认补发' : '建立管理员' }}</el-button><el-button :disabled="busy" @click="closeAdmin()">取消</el-button></div></el-form><div v-else><el-alert :title="adminMode === 'reissue' ? '首次设置链接已补发，请将新链接交给该员工' : '管理员已建立，请将一次性设置链接交给该员工'" role="status" aria-live="polite" type="success" :closable="false" show-icon /><p class="marketplace-note">账号：{{ delivery.account }}<br>有效期至：{{ delivery.expires }}</p><el-input ref="setupLink" :value="delivery.link" type="password" readonly show-password autocomplete="off" label="一次性密码设置链接" aria-label="一次性密码设置链接" /><div class="marketplace-actions"><el-button type="primary" @click="copyLink">复制设置链接</el-button><el-button @click="closeAdmin()">关闭</el-button></div><p v-if="copyNotice" class="marketplace-note" role="status" aria-live="polite">{{ copyNotice }}</p><p class="marketplace-note">链接仅显示本次，关闭后不再保留。</p></div></el-dialog>
  </div>
</template>
<script>
import { marketplaceApi as api, marketplaceError } from '@/api/marketplace';
import { platformCan } from '@/libs/marketplace-navigation';
import { captureContext, currentContext, closeContext } from '@/api/marketplace-aftersale';
import { subscribePlatformAuthEpoch } from '@/libs/platform-auth-epoch';
import '../style.css';
const profile = (row) => ({ name: row ? row.name : '', logo: row ? row.logo : '', after_sale_contact: row ? row.after_sale_contact : '', shipping_note: row ? row.shipping_note : '' });
function merchantResult(data) { if (!data || !Number.isInteger(data.mer_id) || data.mer_id < 1 || typeof data.name !== 'string' || !Number.isInteger(data.review_status)) throw new Error('商家返回不完整，请重新读取'); return data; }
const exitLabels = { fulfillment: '订单履约', payment: '支付责任', refund: '售后退款', settlement: '结算责任' };
const exitStateLabels = { CLEAR: '已核清', OPEN: '仍有待处理责任', UNKNOWN: '尚无法核实' };
function exitMerchantResult(data, id) { const value = merchantResult(data); if (value.mer_id !== id || !(value.closed_at === null || (Number.isSafeInteger(value.closed_at) && value.closed_at > 0))) throw new Error('商家目标或关闭状态未确认，请刷新预检'); return value; }
export default {
  name: 'marketplaceMerchants', data: () => ({ rows: [], count: 0, page: 1, limit: 20, reviewStatus: '', statuses: ['待审核', '审核通过', '未通过'], loading: false, busy: false, error: '', notice: '', editorVisible: false, editorError: '', editId: null, form: profile(null), detailVisible: false, detail: null, adminVisible: false, adminMode: 'create', adminMerchant: null, adminForm: { account: '', name: '' }, reviewVisible: false, flagsVisible: false, stateMerchant: null, stateError: '', reviewForm: 0, flagsForm: { accept_orders: 0, fulfillment_enabled: 1, security_locked: 0 }, adminError: '', adminCreated: false, delivery: null, copyNotice: '', exitLabels, exitStateLabels, exitVisible: false, exitAlive: true, exitContext: null, exitGeneration: 0, exitTarget: null, exitMerchant: null, exitReport: null, exitError: '', exitLoading: false, exitSending: false, exitUnsubscribe: null, exitUnsubscribeEpoch: null }),
  computed: {
    canExitPrecheck() { return this.can('marketplace-merchants-read') && this.can('marketplace-merchants-exit-precheck'); },
    exitRows() { return this.exitReport ? this.exitReport.responsibilities : Object.keys(exitLabels).map(key => ({ key, state: null, count: null, reasons: [] })); },
    exitCanClose() { return !this.busy && !this.exitLoading && !this.exitSending && !this.exitError && !!this.exitContext && currentContext(this.exitContext) && this.canExitPrecheck && this.can('marketplace-merchants-close') && !!this.exitMerchant && this.exitMerchant.mer_id === this.exitTarget && this.exitMerchant.closed_at === null && !!this.exitReport && this.exitReport.mer_id === this.exitTarget && this.exitReport.closed_at === null && this.exitReport.can_close === true && this.exitReport.responsibilities.every(row => row.state === 'CLEAR'); },
    exitSummary() { if (this.exitReport.closed_at !== null) return '商家已关闭，历史资料继续保留'; if (this.exitReport.responsibilities.some(row => row.state === 'UNKNOWN')) return '部分责任尚无法核实，暂不能关闭商家'; if (this.exitReport.responsibilities.some(row => row.state === 'OPEN')) return '仍有待处理责任，暂不能关闭商家'; return this.exitReport.can_close ? '本次责任预检通过，关闭时将重新核对当前责任' : '本次预检未允许关闭商家'; },
    exitSummaryType() { return this.exitReport.closed_at !== null ? 'info' : this.exitReport.can_close && this.exitReport.responsibilities.every(row => row.state === 'CLEAR') ? 'success' : 'warning'; },
  },
  created() { this.load(); this.exitUnsubscribe = this.$store.subscribe(this.syncExitContext); this.exitUnsubscribeEpoch = subscribePlatformAuthEpoch(this.syncExitContext); window.addEventListener('focus', this.syncExitContext); window.addEventListener('storage', this.syncExitContext); },
  beforeDestroy() { this.exitAlive = false; if (this.exitUnsubscribe) this.exitUnsubscribe(); if (this.exitUnsubscribeEpoch) this.exitUnsubscribeEpoch(); window.removeEventListener('focus', this.syncExitContext); window.removeEventListener('storage', this.syncExitContext); this.clearExit(); this.clearDelivery(); },
  beforeRouteLeave(to, from, next) { this.exitVisible = false; this.clearExit(); this.clearDelivery(); next(); },
  methods: {
    formatExitTime(value) { const date = new Date(value * 1000); return Number.isNaN(date.getTime()) ? String(value) : date.toLocaleString(); },
    clearExit() { const active = this.exitLoading || this.exitSending; closeContext(this.exitContext); this.exitContext = null; this.exitGeneration += 1; this.exitTarget = null; this.exitMerchant = null; this.exitReport = null; this.exitError = ''; this.exitLoading = false; this.exitSending = false; if (active) this.busy = false; },
    closeExit(done) { if (this.exitLoading || this.exitSending) return; this.exitVisible = false; this.clearExit(); if (typeof done === 'function') done(); },
    syncExitContext() { if (this.exitContext && (!currentContext(this.exitContext) || !this.canExitPrecheck)) { this.exitVisible = false; this.clearExit(); this.error = '身份或权限已变化，请重新进行退出预检'; } },
    exitCurrent(context, generation, id) { if (!this.exitAlive || context !== this.exitContext || generation !== this.exitGeneration || id !== this.exitTarget) return false; if (!currentContext(context) || !this.canExitPrecheck) { this.syncExitContext(); return false; } return true; },
    async openExit(row) { if (this.busy || this.loading || !this.canExitPrecheck) return; this.clearExit(); this.error = ''; this.notice = ''; this.exitTarget = row.mer_id; this.exitVisible = true; try { this.exitContext = captureContext(this.$store); } catch (error) { this.exitError = '当前登录状态未确认，请重新进入商家列表'; return; } await this.refreshExit(); },
    async refreshExit() {
      if (this.busy || this.exitLoading || this.exitSending || !this.exitContext) return;
      const context = this.exitContext; const generation = this.exitGeneration; const id = this.exitTarget;
      if (!this.exitCurrent(context, generation, id)) return;
      this.busy = true; this.exitLoading = true; this.exitReport = null; this.exitMerchant = null; this.exitError = '';
      try {
        const actual = exitMerchantResult(await api.merchantForExit(id, context), id); if (!this.exitCurrent(context, generation, id)) return; this.exitMerchant = actual;
        const report = await api.merchantExitPrecheck(id, context); if (!this.exitCurrent(context, generation, id)) return;
        if (report.closed_at !== actual.closed_at) throw new Error('商家状态已变化，请刷新预检');
        this.exitReport = report;
      } catch (error) { if (this.exitCurrent(context, generation, id)) this.exitError = marketplaceError(error); }
      finally { if (this.exitCurrent(context, generation, id)) { this.exitLoading = false; this.busy = false; } }
    },
    async refreshExitList(context, generation, id) {
      const query = { page: this.page, limit: this.limit }; if (this.reviewStatus !== '') query.review_status = this.reviewStatus;
      const data = await api.merchantsForExit(query, context); if (!this.exitCurrent(context, generation, id)) return false;
      if (!data || !Array.isArray(data.list) || !Number.isInteger(data.count)) throw new Error('商家列表返回不完整');
      this.rows = data.list.map(merchantResult); this.count = data.count; return true;
    },
    async submitExit() {
      if (!this.exitCanClose) return;
      const context = this.exitContext; const generation = this.exitGeneration; const id = this.exitTarget;
      this.busy = true; this.exitSending = true; this.exitReport = null; this.exitError = ''; this.notice = ''; let returned = false; let confirmed = false;
      try {
        const closed = await api.closeMerchant(id, context); returned = true; if (!this.exitCurrent(context, generation, id)) return;
        const actual = exitMerchantResult(await api.merchantForExit(id, context), id); if (!this.exitCurrent(context, generation, id)) return;
        if (actual.closed_at !== closed.closed_at) throw new Error('商家关闭状态重读未确认');
        confirmed = true; this.exitMerchant = actual; if (this.detail && this.detail.mer_id === id) this.detail = actual;
        if (!await this.refreshExitList(context, generation, id)) return;
        this.exitVisible = false; this.notice = closed.already_closed ? '商家“' + actual.name + '”原已关闭，当前状态已重新核对' : '商家“' + actual.name + '”已正常关闭，当前状态已重新读取';
      } catch (error) { if (this.exitCurrent(context, generation, id)) this.exitError = (confirmed ? '商家关闭已确认，列表刷新未完成：' : returned ? '关闭请求已提交，状态重读未确认，请刷新核对：' : '关闭请求结果未确认，请刷新核对后再决定：') + marketplaceError(error); }
      finally { if (this.exitCurrent(context, generation, id)) { this.exitSending = false; this.busy = false; } }
    },
    can(permission) { return platformCan(this.$store, permission); }, search() { this.page = 1; this.load(); }, changePage(page) { if (!this.loading && !this.busy) { this.page = page; this.load(); } },
    async load(propagate = false) { if (this.loading) { if (propagate === true) throw new Error('列表仍在读取，请稍后刷新'); return; } this.loading = true; this.error = ''; try { const query = { page: this.page, limit: this.limit }; if (this.reviewStatus !== '') query.review_status = this.reviewStatus; const data = await api.merchants(query); if (!data || !Array.isArray(data.list) || !Number.isInteger(data.count)) throw new Error('商家列表返回不完整'); this.rows = data.list.map(merchantResult); this.count = data.count; } catch (error) { this.error = marketplaceError(error); if (propagate === true) throw error; } finally { this.loading = false; } },
    async read(row) { this.error = ''; this.busy = true; try { this.detail = merchantResult(await api.merchant(row.mer_id)); this.detailVisible = true; } catch (error) { this.error = marketplaceError(error); } finally { this.busy = false; } },
    async edit(row) { if (this.busy) return; this.error = ''; this.editorError = ''; this.busy = true; try { const actual = row ? merchantResult(await api.merchant(row.mer_id)) : null; this.editId = actual ? actual.mer_id : null; this.form = profile(actual); this.editorVisible = true; } catch (error) { this.error = marketplaceError(error); } finally { this.busy = false; } },
    closeEditor(done) { if (!this.busy) done(); },
    async save() { if (this.busy) return; this.editorError = ''; this.notice = ''; if (!this.form.name.trim()) { this.editorError = '请填写商家名称'; return; } this.busy = true; let saved = false; try { const actual = merchantResult(await api.saveMerchant(this.editId, { ...profile(this.form), name: this.form.name.trim() })); saved = true; this.editorVisible = false; this.detail = actual; this.detailVisible = true; this.reviewStatus = ''; await this.load(true); this.notice = '商家已保存，当前状态：' + this.statuses[actual.review_status]; } catch (error) { const message = (saved ? '商家已保存，列表刷新未完成：' : '') + marketplaceError(error); if (saved) this.error = message; else this.editorError = message; } finally { this.busy = false; } },
    async approve(row) { if (this.busy) return; this.busy = true; this.error = ''; this.notice = ''; let saved = false; try { const actual = merchantResult(await api.approveMerchant(row.mer_id)); saved = true; if (actual.mer_id !== row.mer_id || actual.review_status !== 1) throw new Error('商家审核状态核对未完成'); const reread = merchantResult(await api.merchant(actual.mer_id)); if (reread.mer_id !== actual.mer_id || reread.review_status !== 1) throw new Error('商家审核状态重读未确认'); if (this.detail && this.detail.mer_id === actual.mer_id) this.detail = reread; await this.load(true); this.notice = '商家审核已完成，当前状态：' + this.statuses[reread.review_status]; } catch (error) { this.error = (saved ? '审核已提交，列表刷新未完成：' : '') + marketplaceError(error); } finally { this.busy = false; } },
    closeState(done) { if (!this.busy) done(); },
    async openReview(row) { if (this.busy) return; this.busy = true; this.error = ''; this.stateError = ''; try { this.stateMerchant = merchantResult(await api.merchant(row.mer_id)); this.reviewForm = this.stateMerchant.review_status; this.reviewVisible = true; } catch (error) { this.error = marketplaceError(error); } finally { this.busy = false; } },
    async openFlags(row) { if (this.busy) return; this.busy = true; this.error = ''; this.stateError = ''; try { this.stateMerchant = merchantResult(await api.merchant(row.mer_id)); if (this.stateMerchant.closed_at !== null) { this.flagsVisible = false; this.error = '商家已关闭，不能通过经营开关重新开店'; return; } this.flagsForm = { accept_orders: this.stateMerchant.accept_orders, fulfillment_enabled: this.stateMerchant.fulfillment_enabled, security_locked: this.stateMerchant.security_locked }; this.flagsVisible = true; } catch (error) { this.error = marketplaceError(error); } finally { this.busy = false; } },
    async saveReview() { if (this.busy) return; this.busy = true; this.stateError = ''; this.notice = ''; let committed = false; try { const id = this.stateMerchant.mer_id; const expected = this.reviewForm; const returned = merchantResult(await api.reviewMerchant(id, expected)); committed = true; if (returned.mer_id !== id || returned.review_status !== expected) throw new Error('商家审核响应未确认'); const actual = merchantResult(await api.merchant(id)); if (actual.mer_id !== id || actual.review_status !== expected) throw new Error('商家审核状态重读未确认'); this.stateMerchant = actual; if (this.detail && this.detail.mer_id === id) this.detail = actual; await this.load(true); this.reviewVisible = false; this.notice = '商家“' + actual.name + '”审核状态已保存：' + this.statuses[actual.review_status]; } catch (error) { this.stateError = (committed ? '审核状态已提交，重读或刷新未完成：' : '') + marketplaceError(error); } finally { this.busy = false; } },
    async saveFlags() { if (this.busy) return; if (!this.stateMerchant || this.stateMerchant.closed_at !== null) { this.stateError = '商家已关闭或状态未确认，不能通过经营开关重新开店'; return; } this.busy = true; this.stateError = ''; this.notice = ''; let committed = false; try { const id = this.stateMerchant.mer_id; const body = { accept_orders: this.flagsForm.accept_orders, fulfillment_enabled: this.flagsForm.fulfillment_enabled, security_locked: this.flagsForm.security_locked }; const returned = merchantResult(await api.merchantFlags(id, body)); committed = true; if (returned.mer_id !== id || Object.keys(body).some((key) => returned[key] !== body[key])) throw new Error('商家开关响应未确认'); const actual = merchantResult(await api.merchant(id)); if (actual.mer_id !== id || Object.keys(body).some((key) => actual[key] !== body[key])) throw new Error('商家开关状态重读未确认'); this.stateMerchant = actual; if (this.detail && this.detail.mer_id === id) this.detail = actual; await this.load(true); this.flagsVisible = false; this.notice = '商家“' + actual.name + '”经营开关已保存并重新读取'; } catch (error) { this.stateError = (committed ? '经营开关已提交，重读或刷新未完成：' : '') + marketplaceError(error); } finally { this.busy = false; } },
    canReissue(row) { return this.can('marketplace-merchants-password-setup-reissue') && row.review_status === 1 && row.security_locked === 0 && row.closed_at === null; },
    openAdmin(row, mode = 'create') { if (this.busy || (mode === 'reissue' && !this.canReissue(row))) return; this.clearDelivery(); this.adminMode = mode; this.adminMerchant = row; this.adminForm = { account: '', name: '' }; this.adminError = ''; this.adminVisible = true; },
    async createAdmin() {
      if (this.busy || this.delivery || this.adminCreated) return; this.adminError = ''; if (!this.adminForm.account.trim()) { this.adminError = '请填写员工账号'; return; } this.busy = true; let created = false; const reissue = this.adminMode === 'reissue';
      try {
        const result = reissue
          ? await api.reissuePasswordSetup(this.adminMerchant.mer_id, this.adminForm.account.trim())
          : await api.createAdminEmployee(this.adminMerchant.mer_id, { account: this.adminForm.account.trim(), name: this.adminForm.name, avatar: '' });
        created = true; this.adminCreated = true;
        const capability = result && result.password_setup; const employee = result && result.employee;
        if (!employee || employee.mer_id !== this.adminMerchant.mer_id || !Number.isInteger(employee.id) || !capability || capability.endpoint !== '/merchantapi/password/setup' || !/^[A-Za-z0-9_-]{43}$/.test(capability.token) || !Number.isInteger(capability.expires_at)) throw new Error(reissue ? '一次性设置凭证返回不完整，请核对员工状态' : '一次性设置凭证返回不完整，请核对管理员状态');
        const link = new URL('/merchant/', window.location.origin); link.hash = '/password-setup?token=' + encodeURIComponent(capability.token);
        this.delivery = { account: employee.account, link: link.href, expires: new Date(capability.expires_at * 1000).toLocaleString() }; this.adminForm = { account: '', name: '' };
      } catch (error) { this.adminError = (created ? (reissue ? '首次设置链接已补发，链接未完整取得，请勿重复补发：' : '管理员已建立，设置链接未完整取得，请勿重复开户：') : '') + marketplaceError(error); }
      finally { this.busy = false; }
    },
    async copyLink() { if (!this.delivery) return; this.copyNotice = ''; try { if (!navigator.clipboard) throw new Error('clipboard unavailable'); await navigator.clipboard.writeText(this.delivery.link); this.copyNotice = '设置链接已复制'; } catch (error) { const input = this.$refs.setupLink && this.$refs.setupLink.$refs.input; if (input) { input.focus(); input.select(); } this.copyNotice = '自动复制未完成，请选中链接后手动复制'; } },
    clearDelivery() { this.delivery = null; this.copyNotice = ''; this.adminMode = 'create'; this.adminForm = { account: '', name: '' }; this.adminMerchant = null; this.adminCreated = false; },
    closeAdmin(done) { if (this.busy) return; this.clearDelivery(); if (typeof done === 'function') done(); else this.adminVisible = false; },
  },
};
</script>
